import styles from "./select-box.module.less";
import { useState, useMemo, forwardRef, useCallback, useId, ForwardedRef, RefObject } from "react";
import { AnimatePresence, motion } from "framer-motion";
import { isNonEmptyArray, multipleClassNames } from "@/core/helpers";
import { FormField, assignToRefs } from "@/core/helpers/form-builder";
import Icon from "@/core/components/primitives/icon/icon";
import InputLabel from "@/core/components/primitives/input-label/input-label";
import InputHelperText from "@/core/components/primitives/input-helper-text/input-helper-text";
import InputError from "@/core/components/primitives/input-error/input-error";
import { SelectItemProps, SelectIconProps } from "@radix-ui/react-select";
import * as Select from "@radix-ui/react-select";

export type SelectBoxOption = {
  value: string;
  label: string;
};

type Props = {
  formField?: FormField;
  options?: Array<SelectBoxOption>;
  value?: string;
  notSelectedText?: string;
  description?: string;
  name?: string;
  shouldShowCheckIcon?: boolean;
  isDisabled?: boolean;
  isRequired?: boolean;
  helperText?: string;
  errorText?: string;
  isValid?: boolean;
  className?: string;
  inputRef?: RefObject<HTMLButtonElement>;
  onChange?: (name: SelectBoxOption["label"], value: SelectBoxOption["value"]) => void;
  "data-testid"?: string;

  /** @deprecated No longer used id prop. useId() is generating the needed value instead. */
  id?: string;
  /** @deprecated No longer supported theming */
  fieldTheme?: "light" | "standard";
  /** @deprecated No longer supported dropdown opening handler */
  onOpen?: () => void;
};

const SelectBox = ({
  formField,
  options,
  value,
  notSelectedText,
  description,
  name,
  shouldShowCheckIcon = true,
  isDisabled,
  isRequired,
  helperText,
  errorText,
  isValid,
  className,
  inputRef,
  onChange,
  "data-testid": dataTestId,
}: Props) => {
  const id = useId();

  const _options = useMemo(() => options ?? formField?.selectBoxOptions ?? [], [options, formField]);
  const _notSelectedText = notSelectedText ?? formField?.placeholder;
  const _value = value ?? formField?.value ?? (_notSelectedText === undefined ? _options[0]?.value : undefined);
  const _description = description ?? formField?.label;
  const _name = name ?? formField?.name;
  const _isRequired = isRequired ?? formField?.isRequired;
  const _helperText = helperText ?? formField?.helperText;
  const _errorText = errorText ?? formField?.errorText;
  const _isValid = isValid ?? formField?.isValid ?? undefined;

  const displayError = _isValid === false;
  const errorId = `${id}-error`;

  const [isOpen, setIsOpen] = useState(false);

  const labelForActiveValue = useMemo(() => {
    if (!isNonEmptyArray(_options)) {
      return "";
    }

    const option = _options.find((option) => option.value === _value);
    return option ? option.label : "";
  }, [_value, _options]);

  /**
   * Handle selecting an option
   */
  const onValueChange = useCallback(
    (newValue: string) => {
      const isNewValueValid = _options.some((option) => option.value === newValue);
      if (onChange && _value !== newValue && isNewValueValid) {
        onChange(_name ?? "", newValue);
      }
    },
    [_name, onChange, _value, _options],
  );

  const listVariants = {
    open: {
      opacity: 1,
      transition: {
        staggerChildren: _options.length > 10 ? 0.02 : 0.05,
      },
    },
    closed: {
      opacity: 0,
    },
  };

  return (
    <div className={className}>
      {_description && <InputLabel label={_description} inputName={id} isRequired={_isRequired} />}
      <Select.Root
        open={isOpen}
        onOpenChange={() => setIsOpen(!isOpen)}
        value={_value}
        disabled={isDisabled}
        onValueChange={onValueChange}
        required={_isRequired}
      >
        <Select.Trigger
          id={id}
          className={styles.toggleButton}
          data-is-open={isOpen}
          data-has-error={displayError}
          aria-invalid={displayError || undefined}
          aria-describedby={displayError ? errorId : undefined}
          ref={(e) => assignToRefs(e, inputRef, formField?.inputRef)}
          data-testid={dataTestId}
        >
          <Select.Value aria-label={labelForActiveValue} placeholder={_notSelectedText}>
            {labelForActiveValue}
          </Select.Value>
          <Select.Icon asChild>
            <SelectIcon shouldShowCheckIcon={!!shouldShowCheckIcon} value={_value} isOpen={isOpen} />
          </Select.Icon>
        </Select.Trigger>
        <AnimatePresence>
          {isOpen && (
            <Select.Content
              asChild
              position="popper"
              sticky="always"
              data-side="bottom"
              className={styles.selectContent}
            >
              <motion.div initial="closed" animate="open" variants={listVariants} className={styles.optionsList}>
                <Select.ScrollUpButton asChild>
                  <motion.div
                    className={multipleClassNames(styles.scrollButton, styles.up)}
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                  >
                    <Icon name="chevron-left" size="l" className={styles.scrollIcon} />
                  </motion.div>
                </Select.ScrollUpButton>
                <Select.Viewport className={styles.optionsViewport}>
                  <Select.Group>
                    {_options.map((option) => {
                      const isSelected = _value === option.value;
                      return (
                        <SelectItem
                          key={option.value}
                          isSelected={isSelected}
                          shouldShowCheckIcon={!!shouldShowCheckIcon}
                          value={option.value}
                        >
                          {option.label}
                        </SelectItem>
                      );
                    })}
                  </Select.Group>
                </Select.Viewport>
                <Select.ScrollDownButton asChild>
                  <motion.div
                    className={multipleClassNames(styles.scrollButton, styles.down)}
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                  >
                    <Icon name="chevron-right" size="l" className={styles.scrollIcon} />
                  </motion.div>
                </Select.ScrollDownButton>
              </motion.div>
            </Select.Content>
          )}
        </AnimatePresence>
      </Select.Root>
      {_helperText && <InputHelperText helperText={_helperText} />}
      <InputError id={errorId} showError={displayError} isRequired={_isRequired} errorText={_errorText} />
    </div>
  );
};

type SelectItemPropsExtended = {
  isSelected: boolean;
  shouldShowCheckIcon: boolean;
} & Omit<SelectItemProps, "asChild">;

const SelectItem = forwardRef<HTMLDivElement, SelectItemPropsExtended>(
  ({ children, isSelected, value, shouldShowCheckIcon, ...props }, forwardedRef) => {
    const itemTextVariants = {
      open: {
        x: 0,
        transition: {
          duration: 0.7,
          type: "spring",
        },
      },
      closed: { x: -300 },
    };

    return (
      <Select.Item
        className={multipleClassNames(styles.optionItem, isSelected && styles.selected)}
        ref={forwardedRef}
        value={value}
        {...props}
      >
        <Select.ItemText asChild>
          <motion.div variants={itemTextVariants}>{children}</motion.div>
        </Select.ItemText>
        {isSelected && shouldShowCheckIcon && (
          <Select.ItemIndicator className="SelectItemIndicator">
            <Icon name="done" className={styles.checkIcon} aria-hidden="true" />
          </Select.ItemIndicator>
        )}
      </Select.Item>
    );
  },
);

SelectItem.displayName = "SelectItem";

const SelectIcon = forwardRef(
  (
    {
      shouldShowCheckIcon,
      value,
      isOpen,
      ...props
    }: {
      shouldShowCheckIcon?: boolean;
      value?: string | number;
      isOpen: boolean;
    } & SelectIconProps,
    forwardedRef: ForwardedRef<HTMLDivElement>,
  ) => {
    const selectionAnimation = {
      initial: { opacity: 0.5, scale: 0 },
      animate: { opacity: 1, scale: 1 },
      exit: { opacity: 0.5, scale: 0 },
      transition: { scale: { duration: 0.2 }, opacity: { duration: 0.3 } },
    };

    const noSelectionAnimation = {
      initial: { opacity: 0.5, scale: 0 },
      animate: { opacity: 1, rotate: isOpen ? 180 : 0, scale: 1 },
      exit: { opacity: 0.5, scale: 0 },
      transition: { scale: { duration: 0.2 }, opacity: { duration: 0.3 } },
    };

    return (
      <AnimatePresence initial={false} mode="popLayout">
        {shouldShowCheckIcon && value && !isOpen ? (
          <motion.div {...selectionAnimation} key="selectedValueIcon" className={styles.icon} ref={forwardedRef}>
            <Icon name="done" size="l" {...props} />
          </motion.div>
        ) : (
          <motion.div {...noSelectionAnimation} key="noValueIcon" className={styles.icon} ref={forwardedRef}>
            <Icon name="expand-more" size="l" {...props} />
          </motion.div>
        )}
      </AnimatePresence>
    );
  },
);

SelectIcon.displayName = "SelectIcon";

export default SelectBox;
